class Solution {
public:
    int shortestSequence(vector<int>& rolls, int k) {
        unordered_set<int> seen;
        int rounds = 0;
        for (int r : rolls) {
            seen.insert(r);
            if ((int)seen.size() == k) {
                rounds++;
                seen.clear();
            }
        }
        return rounds + 1;
    }
};
